<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Ligações</h1><p class="text-muted mb-0">Conversas vinculadas aos leads e analisadas pela IA.</p></div><?php if(Auth::can('calls.manage')):?><a class="btn btn-outline-primary" href="<?=e(url('configuracoes/ligacoes'))?>"><i class="fa-solid fa-gear"></i> Configurar</a><?php endif?></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Data</th><th>Lead</th><th>Atendente</th><th>Duração</th><th>Nota</th><th></th></tr></thead><tbody><?php foreach($calls as $c):?><tr><td><?=e(format_datetime($c['started_at']))?></td><td><?=e($c['lead_name']?:'Não vinculado')?></td><td><?=e($c['agent_name']?:'—')?></td><td><?=e(gmdate('i:s',(int)$c['duration']))?></td><td><?=isset($c['overall_score'])?(int)$c['overall_score'].'/10':'Pendente'?></td><td class="text-end"><a class="btn btn-sm btn-primary" href="<?=e(url('ligacoes/'.$c['id']))?>">Abrir</a></td></tr><?php endforeach?><?php if(!$calls):?><tr><td colspan="6" class="text-center text-muted py-5">Nenhuma ligação sincronizada.</td></tr><?php endif?></tbody></table></div></div>
